def count_islands(g):
    if not g:
        return 0

    rows, cols = len(g), len(g[0])
    count = 0

    def dfs(r, c):
        if 0 <= r < rows and 0 <= c < cols and g[r][c] == '1':
            g[r][c] = '0'
            dfs(r-1, c)
            dfs(r+1, c)
            dfs(r, c-1)
            dfs(r, c+1)

    for r in range(rows):
        for c in range(cols):
            if g[r][c] == '1':
                dfs(r, c)
                count += 1

    return count
